-- LD-057 (WP9, requirements section 25): the register of administrative decisions and assignments about cases. Additive only.
create sequence directive_no_seq;

create table directive (
    id                  uuid primary key default gen_random_uuid(),
    -- Generated by the system (DIR-YYYY-NNNNN); the number on the issuing paper is source_reference_no.
    directive_no        varchar(30)   not null constraint directive_no_unique unique,
    case_id             uuid          not null references legal_case (id),
    task_id             uuid references task (id) on delete set null,
    -- A code of the managed list DIRECTIVE_KIND; null when not specified.
    kind                varchar(40),
    title               varchar(300)  not null constraint directive_title_visible check (length(btrim(title)) > 0),
    details             text,
    directive_date      date          not null,
    -- مصدر التكليف: who issued it (a person, a body, a decision).
    source              varchar(300)  not null constraint directive_source_visible check (length(btrim(source)) > 0),
    source_reference_no varchar(100),
    -- المسؤول عنه: a user of the system and/or free text for an addressee outside it.
    addressee_user_id   uuid references app_user (id),
    addressee_text      varchar(300),
    due_date            date,
    status              varchar(12)   not null default 'NEW' constraint directive_status_known
        check (status in ('NEW', 'IN_PROGRESS', 'DONE', 'CANCELLED')),
    status_note         varchar(1000),
    completed_at        timestamptz,
    version             bigint        not null default 0,
    created_at          timestamptz   not null default now(),
    created_by          uuid          not null,
    updated_at          timestamptz   not null default now(),
    updated_by          uuid          not null,
    search_vector       tsvector generated always as (
        setweight(to_tsvector('simple', library_normalize(title)), 'A')
        || setweight(to_tsvector('simple', library_normalize(directive_no || ' ' || coalesce(source_reference_no, ''))), 'A')
        || setweight(to_tsvector('simple', library_normalize(details)), 'B')
        || setweight(to_tsvector('simple', library_normalize(source)), 'B')
        || setweight(to_tsvector('simple', library_normalize(addressee_text)), 'C')) stored,
    constraint directive_addressee_named check (addressee_user_id is not null or addressee_text is not null),
    constraint directive_text_visible check (
        (details is null or length(btrim(details)) > 0) and (addressee_text is null or length(btrim(addressee_text)) > 0)
        and (source_reference_no is null or length(btrim(source_reference_no)) > 0)
        and (status_note is null or length(btrim(status_note)) > 0)),
    constraint directive_due_not_before_issue check (due_date is null or due_date >= directive_date),
    constraint directive_completed_when_done check ((status = 'DONE') = (completed_at is not null))
);
create index directive_case on directive (case_id, directive_date desc);
create index directive_addressee on directive (addressee_user_id) where status in ('NEW', 'IN_PROGRESS');
create index directive_due on directive (due_date) where status in ('NEW', 'IN_PROGRESS');
create index directive_search on directive using gin (search_vector);
